std::vector<Face_handle> queue;
for (auto fit = triangulation.all_faces_begin(); fit != triangulation.all_faces_end(); ++fit) {
    Face_handle fh = *fit;
    if (triangulation.is_infinite(fh)) {
        fh->set_is_inside(false);
        queue.push_back(fh);
    }
}

size_t head = 0;
while (head < queue.size()) {
    Face_handle curr = queue[head++];
    bool curr_inside = curr->is_inside();

    for (int i = 0; i < 3; ++i) {
        Face_handle neighbor = triangulation.neighbor(curr, i);
        if (neighbor != nullptr && !triangulation.is_infinite(neighbor)) {
            if (triangulation.is_constrained(curr, i)) {
                if (neighbor->is_inside() == curr_inside) {
                    neighbor->set_is_inside(!curr_inside);
                    queue.push_back(neighbor);
                }
            } else {
                if (neighbor->is_inside() != curr_inside) {
                    neighbor->set_is_inside(curr_inside);
                    queue.push_back(neighbor);
                }
            }
        }
    }
}
// END_CODE

